∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {φ : Breakdown.Space → ℝ}
  {L : Breakdown.Space → E} (z w : Breakdown.Space),
  φ z • L z - φ w • L w = φ z • L z - φ w • L z + (φ w • L z - φ w • L w)

∀ (M : Breakdown.CellCert.GivenModel.CellMesh) (K₀ : Fin M.cellCount) {d J : ℕ}
  (E : Fin M.cellCount → Fin (J + 1) → Breakdown.CellCert.GivenModel.CellPoly d) (n : ℤ),
  Breakdown.CellCert.GivenModel.ModeCoverInternal.interiorPoly M K₀ E n ∈ Breakdown.CellCert.CellAnalysis.polyFn d d

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [NormedSpace ℝ E] {f : Breakdown.Space → E} {K K' : ℝ}
  {s : Set Breakdown.Space},
  Breakdown.FracCellInternal.SlopeBoundOn✝ f K s → K ≤ K' → Breakdown.FracCellInternal.SlopeBoundOn✝ f K' s

∀ (D : Breakdown.CellCert.GivenFields.FieldData) (n : ℤ),
  Breakdown.FracCellInternal.quarterTurnData D n =
    { modes := D.modes,
      amp := fun k =>
        if k = n then Breakdown.FracCellInternal.ampScale (-Complex.I) (D.amp k)
        else if k = -n then Breakdown.FracCellInternal.ampScale Complex.I (D.amp k) else D.amp k,
      lowOrder := D.lowOrder, highOrder := D.highOrder, axisOrder := D.axisOrder, guardStream := D.guardStream,
      guardSwirl := D.guardSwirl }

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [NormedSpace ℝ E] {f g : Breakdown.Space → E} {K : ℝ}
  {s : Set Breakdown.Space},
  Breakdown.FracCellInternal.SlopeBoundOn✝ g K s → (∀ z ∈ s, f z = g z) → Breakdown.FracCellInternal.SlopeBoundOn✝ f K s

∀ {ι : Type u_1} {M : Type u_3} {N : Type u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {G : Type u_7}
  [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G) (f : ι → M) (s : Finset ι),
  ∑ x ∈ s, g (f x) = g (∑ x ∈ s, f x)
